from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from datetime import datetime

app = FastAPI()
todos = {}
next_id = 1

class TodoCreate(BaseModel):
    title: str
    priority: str = "medium"

@app.post("/todos", status_code=201)
async def create(todo: TodoCreate):
    global next_id
    new_todo = {"id": next_id, "title": todo.title, "priority": todo.priority, "created_at": str(datetime.now())}
    todos[next_id] = new_todo
    next_id += 1
    return new_todo

@app.get("/todos")
async def get_todos(priority: str | None = None):
    if priority:
        return [t for t in todos.values() if t["priority"] == priority]
    return list(todos.values())

